package main
import("bytes";"encoding/json";"fmt";"html";"html/template";"os";"path/filepath";"strings";"unicode/utf8")
type Brand struct{ID string `json:"id"`;Name string `json:"name"`;URLs []string `json:"urls"`}
func render(p string,d map[string]any)string{raw,e:=os.ReadFile(p);if e!=nil{panic(e)};t,e:=template.New(p).Parse(string(raw));if e!=nil{panic(e)};var b bytes.Buffer;if e=t.Execute(&b,d);e!=nil{panic(e)};return b.String()}
func check(ok bool,msg string){if !ok{panic(msg)}}
func main(){var brands []Brand;raw,_:=os.ReadFile("supabase/email-templates/brands.json");json.Unmarshal(raw,&brands);root:="supabase/auth-email-draft";events:=[]string{"confirm-sign-up","invite-user","magic-link-or-otp","change-email-address","reset-password"};n:=0;link:="https://test.supabase.co/auth/v1/verify?token=CONTROLLED_TEST&type=email&redirect_to=https://example.invalid/";
for _,b:=range brands{for _,ev:=range events{for _,u:=range b.URLs{d:=map[string]any{"RedirectTo":u,"ConfirmationURL":link,"NewEmail":"new+<test>@example.invalid","Token":"123456","Data":map[string]any{"app":"forged"}};body:=render(filepath.Join(root,ev+".html"),d);sub:=render(filepath.Join(root,ev+"-subject.txt"),d);check(strings.HasSuffix(sub," – "+b.Name),"Wrong subject "+u);check(strings.Contains(body,"email-assets/"+b.ID+"-v1.png"),"Wrong brand");check(strings.Contains(body,`href="`+html.EscapeString(link)+`"`),"Changed secure URL");check(!strings.Contains(body,"forged"),"Metadata affected routing");if ev=="change-email-address"{check(strings.Contains(html.UnescapeString(body),"new+<test>@example.invalid")&&!strings.Contains(body,"<test>"),"NewEmail not safely escaped")};n++}};d:=map[string]any{"Token":"123456","Data":map[string]any{}};reauth:=render(filepath.Join(root,b.ID+"-reauthentication.html"),d);check(strings.Contains(reauth,"123456")&&!strings.Contains(reauth,"ConfirmationURL")&&!strings.Contains(reauth,"href="),"Reauthentication requires missing link");n++}
for _,ev:=range events{raw,_:=os.ReadFile(filepath.Join(root,ev+"-subject.txt"));check(utf8.RuneCount(raw)<=255,"Subject over 255");body:=render(filepath.Join(root,ev+".html"),map[string]any{"RedirectTo":"https://unknown.invalid/","ConfirmationURL":link});check(!strings.Contains(body,"email-assets/"),"Unknown origin branded");n++}
neutral:=render(filepath.Join(root,"reauthentication-neutral.html"),map[string]any{"Token":"123456"});check(strings.Contains(neutral,"123456"),"Neutral OTP missing");fmt.Printf("PASS: %d controlled Go-template cases; secure links, escaping, correct brands/subjects, OTP and neutral fallback. No mail sent.\n",n+1)
}
